def longestWellPerformingStretch(hours):
    score = 0
    first = {}
    best = 0
    for j, h in enumerate(hours, 1):
        score += 1 if h > 8 else -1
        if score > 0:
            best = j
        else:
            if score not in first:
                first[score] = j
            i = first.get(score - 1)
            if i is not None and j - i > best:
                best = j - i
    return best
